if (window.PRODUTOS && Array.isArray(window.PRODUTOS_IMPORTADOS)) {
  let proximoId = Math.max(0, ...PRODUTOS.map(produto => produto.id)) + 1;
  PRODUTOS_IMPORTADOS.forEach(produto => {
    produto.id = proximoId++;
    produto.preco = 199;
    produto.caracteristicas = ['Galeria completa do produto', 'Curadoria GLT Imports', produto.liga];
  });
  window.PRODUTOS_IMPORTADOS = PRODUTOS_IMPORTADOS.filter(produto =>
    !produto.nome.includes('Grupo Wanfeng') &&
    produto.nome !== 'Vasco da Gama keychain'
  );
  PRODUTOS.push(...PRODUTOS_IMPORTADOS);
}
